return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-09-26 13:52:22+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - Security Optimizer &#8211; The All-In-One Protection Plugin - Stable (latest release)','language'=>'gl_ES','messages'=>['XML-RPC authentication is disabled for accounts that require 2-factor authentication.'=>'A identificación XML-RPC está desactivada para as contas que requiren a identificación de dous factores.','Activity Log'=>'Rexistro de actividade','Human'=>'Humano','Rate Plugin'=>'Valorar o plugin','Help other users make the best decision and protect their websites.'=>'Axuda a outros usuarios a tomar a mellor decisión e a protexer as súas webs.','Rate your experience with Security Optimizer'=>'Valora a túa experiencia con Security Optimizer','Two-factor authentication forces admin users to login only after providing a token, generated from the Google Authenticator application. If one of your users no longer has access to their Authenticator app and cannot log in to get their backup codes, {{link}}click here{{/link}} to reset their 2-factor authentication.'=>'A identificación de dous factores obriga os usuarios administradores a acceder só despois de proporcionar un token xerado pola aplicación Google Authenticator. Se un dos teus usuarios xa non ten acceso á súa aplicación Authenticator e non pode acceder para obter os seus códigos de reserva, {{link}}fai clic aquí{{/link}} para restablecer a súa identificación de dous factores.','Security Optimizer - Post-hack Actions'=>'Security Optimizer - Accións tras un ataque','Security Optimizer - Activity Log'=>'Security Optimizer - Rexistro de actividade','Security Optimizer - Site Security'=>'Security Optimizer - Seguridade do sitio','Security Optimizer - Login Security'=>'Security Optimizer - Seguridade do acceso','Send occasional emails with tips on improving my site performance, information about new plugin features and exclusive offers by S